from taf.config.scf.calculations import MegazoneScfCalculator, CoamScfCalculator


class UnknownOamType(Exception):
    pass


class DeltaSCFCalculatorSelector():

    @staticmethod
    def get_for(oam_type):
        """
        Get's the calculator implementation for the specific OAM type

        :param oam_type: string for choosing `COAM` or `MZ`
        """
        if oam_type == "MZ":
            return MegazoneScfCalculator
        elif oam_type == "COAM":
            return CoamScfCalculator
        else:
            raise UnknownOamType
